import sys, json, types, os
sys.path.append('storage/shared')

# Patch AdaptiveSampler to v3 sampler if present; otherwise v2; else reference
try:
    from utilities.zephyr2_sampler_v3 import Zephyr2AdaptiveSamplerV3 as BaseSampler
except Exception:
    try:
        from utilities.zephyr2_sampler_v2 import Zephyr2AdaptiveSamplerV2 as BaseSampler
    except Exception:
        from utilities.reference_sampler import ReferenceAdaptiveSampler as BaseSampler

# We need to inject hyperparams (momentum, floor_gain, floor_beta) while keeping the signature expected by callers.
# We do this by wrapping a factory class with the expected __init__(seed, initial_rate, adjustment_factor).
GLOBAL = {"momentum": 0.85, "floor_gain": 0.3, "floor_beta": 1.0}

class PatchedSampler(BaseSampler):
    def __init__(self, seed=0, initial_rate=0.6, adjustment_factor=1.2):
        # Pass through with our tuned hyperparameters when supported
        kwargs = {}
        # Try common params; ignore if BaseSampler doesn't accept them
        try:
            super().__init__(initial_rate=initial_rate,
                             momentum=GLOBAL.get("momentum", 0.85),
                             cooldown=1,
                             # dynamic floor controls if available
                             floor_gain=GLOBAL.get("floor_gain", 0.3),
                             floor_beta=GLOBAL.get("floor_beta", 1.0))
        except TypeError:
            super().__init__(initial_rate=initial_rate)

zmod = types.ModuleType('utilities.adaptive_sampler')
zmod.AdaptiveSampler = PatchedSampler
sys.modules['utilities.adaptive_sampler'] = zmod

# Import hetero model
from coord.hetero_buffered_ring import run_adaptive_hetero_buffered

# Seeds & utils
from utilities.seed_tools import seed_from_str, set_seed, make_rng, mix_seed

base_seed = seed_from_str("Zephyr2-v3-hetero-tuning")
set_seed(base_seed); _, _ = make_rng(base_seed)

cfg = {
    "N": 24, "max_steps": 500,
    "buffer_size": 8, "service_rate": 2,
    "servers": [2, 3],
    "serve_after": False, "bidirectional": True,
    "reliability_means": [0.8, 0.9],
    "reliability_vars": [0.1, 0.2],
    "p0": 0.6, "replicates": 8
}

# Hyperparameter grid for sampler (if supported)
grid = {
    "momentum": [0.85, 0.9],
    "floor_gain": [0.2, 0.4],
    "floor_beta": [1.0, 1.3],
    "target_delta": [0.12, 0.15],  # via targets
}

def summarize(items):
    tf = [x["steps_to_full"] for x in items if x["steps_to_full"] is not None]
    drops_ps = [x["dropped"]/max(1,x["steps"]) for x in items]
    proc_ps = [x["processed"]/max(1,x["steps"]) for x in items]
    qpeaks = [x["queue_peak"] for x in items]
    def mean(xs): return float(sum(xs)/len(xs)) if xs else None
    return {
        "time_to_full_mean": mean(tf),
        "drops_per_step_mean": mean(drops_ps),
        "processed_per_step_mean": mean(proc_ps),
        "queue_peak_mean": mean(qpeaks),
    }

results = {}
for rmean in cfg["reliability_means"]:
    r_key = f"r{rmean}"
    results[r_key] = {}
    for rvar in cfg["reliability_vars"]:
        v_key = f"var{rvar}"
        results[r_key][v_key] = {}
        for srv in cfg["servers"]:
            s_key = f"srv{srv}"
            results[r_key][v_key][s_key] = []
            best = {"metrics": None, "params": None}
            for mom in grid["momentum"]:
                for fg in grid["floor_gain"]:
                    for fb in grid["floor_beta"]:
                        for td in grid["target_delta"]:
                            GLOBAL["momentum"] = mom
                            GLOBAL["floor_gain"] = fg
                            GLOBAL["floor_beta"] = fb
                            runs = []
                            targets = {
                                "p_min": 0.6, "p_max": 1.0,
                                "target_delta": td, "target_dps": 12,
                                "target_drop": 0.02, "target_queue_load": 0.5,
                            }
                            for k in range(cfg["replicates"]):
                                seed = mix_seed(base_seed, int(rmean*1000) + int(rvar*1000) + srv*100 + k)
                                runs.append(run_adaptive_hetero_buffered(
                                    N=cfg["N"], max_steps=cfg["max_steps"], base_seed=seed,
                                    buffer_size=cfg["buffer_size"], service_rate=cfg["service_rate"], servers=srv,
                                    serve_after=cfg["serve_after"], reliability_mean=rmean, reliability_var=rvar,
                                    bidirectional=cfg["bidirectional"], p0=cfg["p0"],
                                    sampler_cfg={"initial_rate": 0.6, "adjustment_factor": 1.2},
                                    targets=targets, track_history=False
                                ))
                            met = summarize(runs)
                            entry = {"params": {"momentum": mom, "floor_gain": fg, "floor_beta": fb, "target_delta": td}, "metrics": met}
                            results[r_key][v_key][s_key].append(entry)
                            # Update best by (drops==0 then min time)
                            drops = met["drops_per_step_mean"] or 0.0
                            time = met["time_to_full_mean"] or 1e9
                            if (best["metrics"] is None) or (drops < (best["metrics"]["drops_per_step_mean"] or 0.0)) or \
                               (drops == (best["metrics"]["drops_per_step_mean"] or 0.0) and time < (best["metrics"]["time_to_full_mean"] or 1e9)):
                                best = {"metrics": met, "params": entry["params"]}
            results[r_key][v_key][s_key] = {
                "best": best,
                "grid_size": len(grid["momentum"])*len(grid["floor_gain"])*len(grid["floor_beta"])*len(grid["target_delta"]),
            }

out_dir = "storage/shared/coord/results"
os.makedirs(out_dir, exist_ok=True)
out_path = os.path.join(out_dir, "zephyr2_v3_hetero_buffered_tuning.json")
with open(out_path, "w", encoding="utf-8") as f:
    json.dump({"config": cfg, "grid": grid, "results": results}, f, indent=2, sort_keys=True)

# Compact summary print
compact = {}
for r_key, by_var in results.items():
    compact[r_key] = {}
    for v_key, by_srv in by_var.items():
        compact[r_key][v_key] = {s_key: by_srv[s_key]["best"] for s_key in by_srv}
print("=== Zephyr II v3 Hetero Buffered Tuning ===")
print(json.dumps({"artifact": out_path, "best": compact}, indent=2))
print("Tuning run complete.")

